function onclickUser(n){$("txtUserName").value==n&&($("txtUserName").className="text_normal",$("txtUserName").value="")}function onblurUser(n){$("txtUserName").value==""&&($("txtUserName").className="text_italic",$("txtUserName").value=n)}function onKeyPressUser(n,t){t||(t=window.event);var i=t.keyCode?t.keyCode:t.which;if(i==13)return $(n).click(),!1}function InitTagSuggestion(){initAutoComplete("txtUserName","../../../_GlobalResources/Handlers/QueryUserName.ashx?custid="+_page.custid+"&isdir=1")}